from taf.collectors.base import CreatingOamConnection
from taf.sbts.oam.coam.admin.facade import AdminConnection
from taf.gnb.oam.coam.cu.facade import CUConnection
from taf.gnb.oam.coam.vdu.facade import VduConnection
from taf.internal.core import NamedComponentFactory
from taf.vran.vdu.enb.rest.facade import LTEvDUConnection

from .collector import (
    CoamSnapshotCollector,
    CoamCUSnapshotCollector,
    CoamVDUSnapshotCollector,
    AsynchronousCoamCUSnapshotCollector,
    AsynchronousCoamVDUSnapshotCollector,
    SbtsScrelCollector,
    CoamVDUScrelCollector,
    CoamCUScrelCollector,
    AsynchronousCoamCUScrelCollector,
    AsynchronousCoamVDUScrelCollector,
    LteVduSnapshotCollector
)

import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SbtsSnapshotCollectorFactory(CreatingOamConnection(AdminConnection, attr_name="managed_admin_connection"),
                                   NamedComponentFactory):

    """
    Factory to create a CoamSnapshotCollector.
    """
    _optional_parameters = {"target_file_name", "coverage", "force", "timeout", "reg_exp_filter", "reason",
                            "network_cell_dns"}
    _product_class = CoamSnapshotCollector


class CoamCUSnapshotCollectorFactory(CreatingOamConnection(CUConnection, attr_name="cu_connection"),
                                     NamedComponentFactory):
    """
    Factory to create a CoamCUSnapshotCollector.
    """
    _optional_parameters = {"request_timeout", "operation_timeout", "compressed", "filter_regx", "coverage"}
    _product_class = CoamCUSnapshotCollector


class CoamVDUSnapshotCollectorFactory(CreatingOamConnection(VduConnection, attr_name="managed_vdu_connection"),
                                      NamedComponentFactory):
    """
    Factory to create a CoamVDUSnapshotCollector.
    """
    _optional_parameters = {"request_timeout", "operation_timeout", "compressed_or_not", "filter_regx", "coverage"}
    _product_class = CoamVDUSnapshotCollector


class AsynchronousCoamCUSnapshotCollectorFactory(CreatingOamConnection(CUConnection, attr_name="cu_connection"),
                                                 NamedComponentFactory):
    """
    Factory to create a AsynchronousCoamCUSnapshotCollector.
    """
    _optional_parameters = {"request_timeout", "operation_timeout", "compressed", "filter_regx", "coverage"}
    _product_class = AsynchronousCoamCUSnapshotCollector


class AsynchronousCoamVDUSnapshotCollectorFactory(CreatingOamConnection(VduConnection,
                                                                        attr_name="managed_vdu_connection"),
                                                  NamedComponentFactory):
    """
    Factory to create a AsynchronousCoamVDUSnapshotCollector.
    """
    _optional_parameters = {"request_timeout", "operation_timeout", "compressed_or_not", "filter_regx", "coverage"}
