class SbtsScrelCollectorFactory(CreatingOamConnection(AdminConnection, attr_name="managed_admin_connection"),
                                NamedComponentFactory):
    """
    Factory to create a SbtsCrelCollector.
    """
    _optional_parameters = {"target_file_name", "include_pmfm_data", "timeout"}
    _product_class = SbtsScrelCollector


class CoamScrelCollectorFactoryBase:
    """
    Base class to create a CoamScrelCollector.
    """
    _optional_parameters = {"coverage", "timeout", "compressed"}


class CoamVDUScrelCollectorFactory(CreatingOamConnection(VduConnection, attr_name="managed_vdu_connection"),
                                   CoamScrelCollectorFactoryBase, NamedComponentFactory):
    """
    Factory to create a CoamVDUScrelCollector.
    """
    _product_class = CoamVDUScrelCollector


class CoamCUScrelCollectorFactory(CreatingOamConnection(CUConnection, attr_name="cu_connection"),
                                  CoamScrelCollectorFactoryBase, NamedComponentFactory):
    """
    Factory to create a CoamCUCrelCollector.
    """
    _product_class = CoamCUScrelCollector

class AsynchronousCoamVDUScrelCollectorFactory(CreatingOamConnection(VduConnection, attr_name="managed_vdu_connection"),
                                               CoamScrelCollectorFactoryBase, NamedComponentFactory):
    """
    Factory to create a AsynchronousCoamVDUScrelCollector.
    """
    _product_class = AsynchronousCoamVDUScrelCollector


class AsynchronousCoamCUScrelCollectorFactory(CreatingOamConnection(CUConnection, attr_name="cu_connection"),
                                              CoamScrelCollectorFactoryBase, NamedComponentFactory):
    """
    Factory to create a AsynchronousCoamCUCrelCollector.
    """
    _product_class = AsynchronousCoamCUScrelCollector


class LteVduSnapshotCollectorFactoryBase(CreatingOamConnection(LTEvDUConnection, attr_name="managed_oam_connection"),
                                         NamedComponentFactory):
    """
    Base class to create an LTEVduSnapshotCollector.
    """
    _optional_parameters = {"coverage", "timeout", "compressed"}


class LteVduSnapshotCollectorFactory(LteVduSnapshotCollectorFactoryBase):

    """
    Factory for LTEVduSnapshotCollector.
    """
    _product_class = LteVduSnapshotCollector
